    def andd(self):
        l=self.un()
        while self.pk()=='&': self.eat(); r=self.un(); l=('and',l,r)
        return l
    def un(self):
        if self.pk()=='~': self.eat(); return ('not',self.un())
        return self.atom()
    def atom(self):
        v=self.eat()
        if v=='(':
