def parse_lut_init(typ):
    m2=re.search(r'LUT(\d)', typ); n=int(m2.group(1)) if m2 else 6
    m=re.search(r"INIT=(\d+)'([01]+)", typ)
    if not m: return n,None
    return n, int(m.group(2),2)

def lut_eval(n,init,inps):
    idx=0
    for k in range(n):
        if inps[k]: idx|=(1<<k)
    return (init>>idx)&1

gates=[]; fflist=[]
for typ,iname,pins in instances:
    if 'LUT' in typ:
        n,init=parse_lut_init(typ)
        O=pins.get('O')
        isigs=[pins.get('I%d'%k) for k in range(n)]
        if init is None:
            def f(env,_typ=typ,_isigs=isigs,_n=n):
                iv={}
                for k in range(_n):
                    iv['I%d'%k]=env.get(_isigs[k],0) if _isigs[k] else 0
                return eval_module(_typ,iv)
            gates.append((O,f))
        else:
            def f(env,_isigs=isigs,_n=n,_init=init):
                vals=[env.get(_isigs[k],0) if _isigs[k] else 0 for k in range(_n)]
                return lut_eval(_n,_init,vals)
            gates.append((O,f))
    elif typ in ('MUXCY','MUXF7','MUXF8','XORCY'):
        O=pins.get('O')
        if typ=='MUXCY':
            f=lambda env,p=pins: (env.get(p['CI'],0) if env.get(p['S'],0) else env.get(p['DI'],0))
        elif typ in ('MUXF7','MUXF8'):
            f=lambda env,p=pins: env.get(p['I1'],0) if env.get(p['S'],0) else env.get(p['I0'],0)
        else:
            f=lambda env,p=pins: env.get(p['CI'],0)^env.get(p['LI'],0)
        gates.append((O,f))
    elif 'FDCE' in typ or 'FDPE' in typ:
        fflist.append((pins.get('Q'),pins.get('D'),'CLR' if 'FDCE' in typ else 'PRE',pins))

state={Q:0 for Q,D,kind,pins in fflist}

def settle(env):
    for _ in range(2000):
        ch=False
        for O,f in gates:
            if O is None: continue
            v=f(env)
            if env.get(O,-1)!=v: env[O]=v; ch=True
        if not ch: break
    return env

def clock(env, reset=0):
    settle(env)
    newstate={}
    for Q,D,kind,pins in fflist:
        CE=pins.get('CE','1'); ce = env.get(CE,1) if CE not in ('0','1') else int(CE)
        dval = env.get(D,0) if D not in ('0','1') else int(D)
        nxt = dval if ce else state[Q]
        if kind=='CLR':
            clr=pins.get('CLR','0'); clrv=env.get(clr,0) if clr not in ('0','1') else int(clr)
            if reset or clrv: nxt=0
        else:
            pre=pins.get('PRE','0'); prev=env.get(pre,0) if pre not in ('0','1') else int(pre)
            if prev: nxt=1
        newstate[Q]=nxt
    state.update(newstate)
    settle(env)
    return env

def set_bits(env, base, width, val):
    for i in range(width):
        env[f'{base}[{i}]']=(val>>i)&1

def reset():
    for _ in range(2):
        env=dict(state); env['io_inputDone']=0; env['reset']=1
        set_bits(env,'io_input',7,0); set_bits(env,'io_temp',8,0)
        clock(env,reset=1)
    env=dict(state); env['io_inputDone']=0; env['reset']=0
    set_bits(env,'io_input',7,0); set_bits(env,'io_temp',8,0)
    clock(env,reset=0)

def sendByte(byte, temp=0):
    b=byte&0x7f
    env=dict(state); env['io_inputDone']=1; env['reset']=0
    set_bits(env,'io_input',7,b); set_bits(env,'io_temp',8,temp)
    clock(env,reset=0)
    env=dict(state); env['io_inputDone']=0; env['reset']=0
    set_bits(env,'io_input',7,b); set_bits(env,'io_temp',8,temp)
    clock(env,reset=0)

def get_reg(name, width):
    return sum(state.get(f'{name}[{i}]',0)<<i for i in range(width))

