import re, sys, json

src = open('/challenge/CtfTask.v').read()
lines = src.splitlines()

def norm(s):
    s = s.strip()
    return s

# ---- parse module definitions ----
# Each module: name, list of (lhs, expr_str, expr_ast)
# We distinguish LUT (assign-based combinational) vs FDCE/FDPE (sequential)

moddefs = {}   # name -> {'type','params','assigns':[(lhs, expr_ast)], 'io':[...]}
i = 0
while i < len(lines):
    m = re.match(r'\s*module\s+(\S+)\s*\(', lines[i])
    if m:
        name = m.group(1).replace('\\','')
        j = i+1
        assigns = []
        body = []
        while j < len(lines) and 'endmodule' not in lines[j]:
            body.append(lines[j])
            j += 1
        # classify
        typ = 'comb'
        if 'always @(posedge' in '\n'.join(body) or 'reg Q' in '\n'.join(body):
            typ = 'ff'
        moddefs[name] = {'type': typ, 'body': body, 'line': i}
        i = j
    i += 1

print("parsed module defs:", len(moddefs))

# Build evaluator for combinational assign-based modules (LUTs)
# parse assign statements into boolean AST
class P:
    def __init__(self,t): self.t=t; self.p=0
    def pk(self): return self.t[self.p] if self.p<len(self.t) else None
    def eat(self): v=self.t[self.p]; self.p+=1; return v
    def tern(self):
        c=self.orr()
        if self.pk()=='?':
            self.eat(); a=self.tern(); self.eat(); b=self.tern(); return ('if',c,a,b)
        return c
    def orr(self):
        l=self.xor()
        while self.pk()=='|': self.eat(); r=self.xor(); l=('or',l,r)
        return l
    def xor(self):
        l=self.andd()
        while self.pk()=='^': self.eat(); r=self.andd(); l=('xor',l,r)
        return l
    def andd(self):
        l=self.un()
        while self.pk()=='&': self.eat(); r=self.un(); l=('and',l,r)
        return l
    def un(self):
        if self.pk()=='~': self.eat(); return ('not',self.un())
        return self.atom()
    def atom(self):
        v=self.eat()
        if v=='(': e=self.tern(); self.eat(); return e
        return ('var',v)

def tokenize(s):
    toks=[]; k=0
    while k<len(s):
        c=s[k]
        if c.isspace(): k+=1; continue
        if c in '?:~&|^()': toks.append(c); k+=1; continue
        m=re.match(r"[A-Za-z0-9_$\[\].']+", s[k:])
        if m: toks.append(m.group(0)); k+=len(m.group(0)); continue
        k+=1
    return toks

def ev(e,env):
    t=e[0]
    if t=='var': return env.get(e[1],0)
    if t=='not': return 1-ev(e[1],env)
    if t=='and': return ev(e[1],env)&ev(e[2],env)
    if t=='or': return ev(e[1],env)|ev(e[2],env)
    if t=='xor': return ev(e[1],env)^ev(e[2],env)
    if t=='if': return ev(e[2],env) if ev(e[1],env) else ev(e[3],env)
    return 0

# parse assign statements in each comb module
comb_defs = {}  # name -> list of (lhs, ast)
ff_defs = {}    # name -> {'init':0/1, 'pre':bool}

for name, d in moddefs.items():
    if d['type'] == 'comb':
        assigns = []
        for l in d['body']:
            a = re.match(r'\s*assign\s+(.+?)\s*=\s*(.+?)\s*;', l)
            if a:
                lhs = a.group(1).replace('\\','').strip()
                ast = P(tokenize(a.group(2))).tern()
                assigns.append((lhs, ast))
        comb_defs[name] = assigns
    else:
        body = '\n'.join(d['body'])
        pre = 'PRE' in name or ('PRE' in body and 'posedge PRE' in body)
        m = re.search(r'Q\s*=\s*1\'([hb])([01])', body)
        init = 0
        if m: init = int(m.group(2))
        ff_defs[name] = {'pre': pre, 'init': init}

print("comb defs:", len(comb_defs), "ff defs:", len(ff_defs))

# ---- parse top module instantiations ----
# find CtfTask module body
top_start = None
for i,l in enumerate(lines):
    if re.match(r'\s*module\s+CtfTask\s*\(', l):
        top_start = i; break

# collect instantiations: lines like "MODULENAME instname (" then ".PORT(sig),"
insts = []  # list of {'mod': name, 'inst': iname, 'ports': {port: siglist}}
j = top_start+1
while j < len(lines) and 'endmodule' not in lines[j]:
    m = re.match(r'\s*(\S+)\s+(_\d+)\s*\(', lines[j])
    if m:
        modfull = m.group(1)
        mod = modfull.replace('\\','')
        iname = m.group(2)
        ports = {}
        k = j+1
        while k < len(lines) and ');' not in lines[k]:
            pm = re.match(r'\s*\.([A-Za-z0-9_]+)\s*\(\s*(.*?)\s*\)\s*,?\s*$', lines[k])
            if pm:
                port = pm.group(1)
                val = pm.group(2)
                # could be multiple concatenated; keep raw
                ports[port] = val
            k += 1
        insts.append({'mod': mod, 'inst': iname, 'ports': ports})
        j = k
    j += 1

print("total instantiations:", len(insts))
from collections import Counter
c = Counter(x['mod'][:20] for x in insts)
for k,v in c.most_common(20):
    print(f"  {k}: {v}")

# save for later use
json.dump({'insts': insts}, open('/work/insts.json','w'))

